def rank_scores(records):
    return sorted(records, key=lambda record: record[1], reverse=True)

print(rank_scores([("A", 80), ("B", 90), ("C", 90)]))
print(rank_scores([]))
print(rank_scores([("Z", 5), ("A", 5)]))

def sort_by_score_name(records):
    return sorted(records, key=lambda record: (-record[1], record[0]))

print(sort_by_score_name([("Z", 80), ("B", 90), ("A", 90)]))
print(sort_by_score_name([]))
print(sort_by_score_name([("B", 2), ("A", 2), ("B", 1)]))

def sort_tasks(tasks):
    return sorted(tasks, key=lambda task: (not task[1], task[2]))

print(sort_tasks([("A", False, 2), ("B", True, 5), ("C", True, 2), ("D", True, 2)]))
print(sort_tasks([]))
print(sort_tasks([("Z", False, 3), ("A", False, 3)]))

def key_call_report(values):
    calls = []
    def get_key(value):
        calls.append(value)
        return abs(value)
    result = sorted(values, key=get_key)
    return result, calls

print(key_call_report([2, -2, 1]))
print(key_call_report([]))
print(key_call_report([-3, 0, -1]))
